-- =====================================================================
-- Helper Academy — v33: partner meters
--   word partners can sit on a meter, like words do: light rain → steady rain → heavy rain → pouring rain.
--   word_partners gets a tags column using the same "📶 <meter>: <level>" format as words.
--   61 partners on 18 meters (new phrases are added, existing ones get their level).
-- Generated by tools/words/build_v33.py from tools/words/partners.py. Safe to re-run. Run AFTER v32.
-- =====================================================================
alter table public.word_partners add column if not exists tags text[] not null default '{}';

insert into public.word_partners (word_id, kind, phrase, partner, position, tags, owner_id)
select w.id, x.kind, x.phrase, x.partner, x.pos, array[x.tag], (select p.id from public.profiles p join auth.users u on u.id = p.id where u.email = 'albarq2000@hotmail.com')
from (values
  ('rain', 'adjective', 'light rain', 'light', '📶 Rain · light → pouring: 1', 500),
  ('rain', 'adjective', 'steady rain', 'steady', '📶 Rain · light → pouring: 3', 501),
  ('rain', 'adjective', 'heavy rain', 'heavy', '📶 Rain · light → pouring: 4', 502),
  ('rain', 'adjective', 'pouring rain', 'pouring', '📶 Rain · light → pouring: 5', 503),
  ('wind', 'adjective', 'gentle wind', 'gentle', '📶 Wind · gentle → howling: 1', 504),
  ('wind', 'adjective', 'strong wind', 'strong', '📶 Wind · gentle → howling: 4', 505),
  ('wind', 'adjective', 'howling wind', 'howling', '📶 Wind · gentle → howling: 5', 506),
  ('storm', 'adjective', 'mild storm', 'mild', '📶 Storm · mild → violent: 1', 507),
  ('storm', 'adjective', 'heavy storm', 'heavy', '📶 Storm · mild → violent: 4', 508),
  ('storm', 'adjective', 'violent storm', 'violent', '📶 Storm · mild → violent: 5', 509),
  ('snow', 'adjective', 'light snow', 'light', '📶 Snow · light → heavy: 1', 510),
  ('snow', 'adjective', 'steady snow', 'steady', '📶 Snow · light → heavy: 3', 511),
  ('snow', 'adjective', 'heavy snow', 'heavy', '📶 Snow · light → heavy: 5', 512),
  ('sun', 'adjective', 'weak sun', 'weak', '📶 Sun · weak → blazing: 1', 513),
  ('sun', 'adjective', 'bright sun', 'bright', '📶 Sun · weak → blazing: 3', 514),
  ('sun', 'adjective', 'hot sun', 'hot', '📶 Sun · weak → blazing: 4', 515),
  ('sun', 'adjective', 'blazing sun', 'blazing', '📶 Sun · weak → blazing: 5', 516),
  ('noise', 'adjective', 'faint noise', 'faint', '📶 Noise · faint → deafening: 1', 517),
  ('noise', 'adjective', 'loud noise', 'loud', '📶 Noise · faint → deafening: 4', 518),
  ('noise', 'adjective', 'deafening noise', 'deafening', '📶 Noise · faint → deafening: 5', 519),
  ('voice', 'adjective', 'whispering voice', 'whispering', '📶 Voice · whispering → booming: 0', 520),
  ('voice', 'adjective', 'soft voice', 'soft', '📶 Voice · whispering → booming: 1', 521),
  ('voice', 'adjective', 'quiet voice', 'quiet', '📶 Voice · whispering → booming: 2', 522),
  ('voice', 'adjective', 'loud voice', 'loud', '📶 Voice · whispering → booming: 4', 523),
  ('voice', 'adjective', 'booming voice', 'booming', '📶 Voice · whispering → booming: 5', 524),
  ('speak', 'adverb', 'speak in a whisper', 'in a whisper', '📶 Speak · whisper → shout: 0', 525),
  ('speak', 'adverb', 'speak softly', 'softly', '📶 Speak · whisper → shout: 1', 526),
  ('speak', 'adverb', 'speak loudly', 'loudly', '📶 Speak · whisper → shout: 4', 527),
  ('speak', 'adverb', 'speak at the top of your voice', 'at the top of your voice', '📶 Speak · whisper → shout: 5', 528),
  ('laugh', 'adverb', 'laugh quietly', 'quietly', '📶 Laugh · quietly → loudly: 1', 529),
  ('laugh', 'adverb', 'laugh happily', 'happily', '📶 Laugh · quietly → loudly: 3', 530),
  ('laugh', 'adverb', 'laugh loudly', 'loudly', '📶 Laugh · quietly → loudly: 4', 531),
  ('mistake', 'adjective', 'tiny mistake', 'tiny', '📶 Mistake · tiny → terrible: 0', 532),
  ('mistake', 'adjective', 'silly mistake', 'silly', '📶 Mistake · tiny → terrible: 1', 533),
  ('mistake', 'adjective', 'careless mistake', 'careless', '📶 Mistake · tiny → terrible: 2', 534),
  ('mistake', 'adjective', 'big mistake', 'big', '📶 Mistake · tiny → terrible: 4', 535),
  ('mistake', 'adjective', 'terrible mistake', 'terrible', '📶 Mistake · tiny → terrible: 5', 536),
  ('trouble', 'adjective', 'a little trouble', 'a little', '📶 Trouble · a little → serious: 1', 537),
  ('trouble', 'adjective', 'big trouble', 'big', '📶 Trouble · a little → serious: 4', 538),
  ('trouble', 'adjective', 'serious trouble', 'serious', '📶 Trouble · a little → serious: 5', 539),
  ('effort', 'adjective', 'small effort', 'small', '📶 Effort · small → great: 1', 540),
  ('effort', 'adjective', 'real effort', 'real', '📶 Effort · small → great: 3', 541),
  ('effort', 'adjective', 'big effort', 'big', '📶 Effort · small → great: 4', 542),
  ('effort', 'adjective', 'great effort', 'great', '📶 Effort · small → great: 5', 543),
  ('idea', 'adjective', 'bad idea', 'bad', '📶 Idea · bad ⇄ brilliant: -3', 544),
  ('idea', 'adjective', 'good idea', 'good', '📶 Idea · bad ⇄ brilliant: +2', 545),
  ('idea', 'adjective', 'clever idea', 'clever', '📶 Idea · bad ⇄ brilliant: +4', 546),
  ('idea', 'adjective', 'great idea', 'great', '📶 Idea · bad ⇄ brilliant: +4', 547),
  ('idea', 'adjective', 'brilliant idea', 'brilliant', '📶 Idea · bad ⇄ brilliant: +5', 548),
  ('fun', 'adjective', 'a little fun', 'a little', '📶 Fun · a little → great: 1', 549),
  ('fun', 'adjective', 'lots of fun', 'lots of', '📶 Fun · a little → great: 4', 550),
  ('fun', 'adjective', 'great fun', 'great', '📶 Fun · a little → great: 5', 551),
  ('impact', 'adjective', 'small impact', 'small', '📶 Impact · small → huge: 1', 552),
  ('impact', 'adjective', 'big impact', 'big', '📶 Impact · small → huge: 3', 553),
  ('impact', 'adjective', 'huge impact', 'huge', '📶 Impact · small → huge: 5', 554),
  ('nervous', 'adverb', 'a bit nervous', 'a bit', '📶 Nervous · a bit → very: 1', 555),
  ('nervous', 'adverb', 'very nervous', 'very', '📶 Nervous · a bit → very: 4', 556),
  ('fortunate', 'adverb', 'very fortunate', 'very', '📶 Fortunate · very → extremely: 3', 557),
  ('fortunate', 'adverb', 'extremely fortunate', 'extremely', '📶 Fortunate · very → extremely: 5', 558),
  ('obvious', 'adverb', 'very obvious', 'very', '📶 Obvious · very → perfectly: 3', 559),
  ('obvious', 'adverb', 'perfectly obvious', 'perfectly', '📶 Obvious · very → perfectly: 5', 560)
) as x(hw, kind, phrase, partner, tag, pos)
join public.words w on w.lang = 'en' and lower(w.headword) = x.hw and w.sense = ''
on conflict (word_id, lower(phrase)) do update set
  tags = (select array(select distinct t from unnest(array(select t0 from unnest(public.word_partners.tags) t0 where t0 not like '📶 %') || excluded.tags) t)),
  partner = excluded.partner;

-- check
select count(*) filter (where exists (select 1 from unnest(tags) t where t like '📶 %')) as partners_on_meters,
       count(distinct (select split_part(t, ':', 1) from unnest(tags) t where t like '📶 %' limit 1)) as meters,
       count(*) as partners
from public.word_partners;
